// Signed links and tokens. Pure functions (node:crypto only) so they can be unit-tested directly.
//
// Survey link:   /r/<surveyId>.<rating>.<sig>
//   sig = HMAC(secret, "link:v1|<surveyId>|<rating>")  -> nobody can forge a link for another
//   survey or change the rating in the URL.
// Metadata sig:  optional "s" query param covering email/agent/ticket. Only links generated by
//   our own server (API sends) carry it; helpdesk merge-tag links cannot, so their metadata is
//   stored as "unverified".
// Response token: lets the person who clicked add a comment / confirm, for a limited time.
import { createHmac, timingSafeEqual } from "node:crypto";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const SIG_RE = /^[A-Za-z0-9_-]{22}$/; // 16 bytes, base64url
const LINK_TOKEN_RE = /^([0-9a-f-]{36})\.(\d{1,2})\.([A-Za-z0-9_-]{22})$/;

function hmac(secret: string, message: string, bytes = 16): string {
  if (!secret || secret.length < 32) throw new Error("signing secret missing or too short");
  return createHmac("sha256", secret).update(message, "utf8").digest().subarray(0, bytes).toString("base64url");
}

function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a, "utf8");
  const bb = Buffer.from(b, "utf8");
  if (ab.length !== bb.length) return false;
  return timingSafeEqual(ab, bb);
}

export function isUuid(value: string): boolean {
  return UUID_RE.test(value);
}

// ---------------------------------------------------------------------------
// Survey links
// ---------------------------------------------------------------------------

export function signSurveyLink(secret: string, surveyId: string, rating: number): string {
  if (!isUuid(surveyId)) throw new Error("invalid survey id");
  if (!Number.isInteger(rating) || rating < 0 || rating > 10) throw new Error("invalid rating");
  return hmac(secret, `link:v1|${surveyId}|${rating}`);
}

export function buildLinkToken(secret: string, surveyId: string, rating: number): string {
  return `${surveyId}.${rating}.${signSurveyLink(secret, surveyId, rating)}`;
}

export type ParsedLinkToken = { surveyId: string; rating: number; sig: string };

export function parseLinkToken(token: string): ParsedLinkToken | null {
  if (typeof token !== "string" || token.length > 80) return null;
  const m = LINK_TOKEN_RE.exec(token);
  if (!m) return null;
  const [, surveyId, ratingStr, sig] = m;
  if (!surveyId || !ratingStr || !sig || !isUuid(surveyId)) return null;
  if (ratingStr.length > 1 && ratingStr.startsWith("0")) return null; // no "05"
  const rating = Number(ratingStr);
  if (!Number.isInteger(rating) || rating < 0 || rating > 10) return null;
  return { surveyId, rating, sig };
}

/** Accepts the current secret and, during rotation, the previous one. */
export function verifyLinkToken(secrets: readonly string[], parsed: ParsedLinkToken): boolean {
  if (!SIG_RE.test(parsed.sig)) return false;
  let ok = false;
  for (const secret of secrets) {
    if (!secret) continue;
    // Evaluate every secret (no early exit) to keep timing independent of which one matched.
    if (safeEqual(signSurveyLink(secret, parsed.surveyId, parsed.rating), parsed.sig)) ok = true;
  }
  return ok;
}

// ---------------------------------------------------------------------------
// Metadata signature (for links our own server generates per recipient)
// ---------------------------------------------------------------------------

export type LinkMetadata = { email?: string | null; agent?: string | null; ticket?: string | null };

function metadataMessage(surveyId: string, m: LinkMetadata): string {
  // JSON.stringify of a fixed-order array avoids delimiter-injection ambiguities.
  return `meta:v1|${surveyId}|${JSON.stringify([m.email ?? "", m.agent ?? "", m.ticket ?? ""])}`;
}

export function signMetadata(secret: string, surveyId: string, m: LinkMetadata): string {
  return hmac(secret, metadataMessage(surveyId, m));
}

export function verifyMetadata(
  secrets: readonly string[],
  surveyId: string,
  m: LinkMetadata,
  sig: string | null | undefined,
): boolean {
  if (!sig || !SIG_RE.test(sig)) return false;
  let ok = false;
  for (const secret of secrets) {
    if (!secret) continue;
    if (safeEqual(signMetadata(secret, surveyId, m), sig)) ok = true;
  }
  return ok;
}

// ---------------------------------------------------------------------------
// Response tokens (thank-you page -> confirm / comment)
// ---------------------------------------------------------------------------

export const RESPONSE_TOKEN_TTL_SECONDS = 7 * 24 * 60 * 60;

export function createResponseToken(
  secret: string,
  responseId: string,
  nowSeconds: number = Math.floor(Date.now() / 1000),
  ttlSeconds: number = RESPONSE_TOKEN_TTL_SECONDS,
): string {
  if (!isUuid(responseId)) throw new Error("invalid response id");
  const exp = nowSeconds + ttlSeconds;
  return `${exp}.${hmac(secret, `resp:v1|${responseId}|${exp}`)}`;
}

export function verifyResponseToken(
  secret: string,
  responseId: string,
  token: string,
  nowSeconds: number = Math.floor(Date.now() / 1000),
): boolean {
  if (typeof token !== "string" || token.length > 60 || !isUuid(responseId)) return false;
  const m = /^(\d{10})\.([A-Za-z0-9_-]{22})$/.exec(token);
  if (!m || !m[1] || !m[2]) return false;
  const exp = Number(m[1]);
  if (exp < nowSeconds) return false;
  if (exp > nowSeconds + RESPONSE_TOKEN_TTL_SECONDS + 60) return false; // reject absurd expiries
  return safeEqual(hmac(secret, `resp:v1|${responseId}|${exp}`), m[2]);
}

// ---------------------------------------------------------------------------
// Purpose-bound short-lived tokens (e.g. "this browser just used a password-reset link")
// ---------------------------------------------------------------------------

export function createPurposeToken(
  secret: string,
  purpose: string,
  subject: string,
  ttlSeconds: number,
  nowSeconds: number = Math.floor(Date.now() / 1000),
): string {
  if (!/^[a-z-]{3,30}$/.test(purpose) || !isUuid(subject)) throw new Error("invalid purpose token input");
  const exp = nowSeconds + ttlSeconds;
  return `${exp}.${hmac(secret, `purpose:v1|${purpose}|${subject}|${exp}`)}`;
}

export function verifyPurposeToken(
  secret: string,
  purpose: string,
  subject: string,
  token: string | undefined | null,
  maxTtlSeconds: number,
  nowSeconds: number = Math.floor(Date.now() / 1000),
): boolean {
  if (typeof token !== "string" || token.length > 60 || !isUuid(subject)) return false;
  const m = /^(\d{10})\.([A-Za-z0-9_-]{22})$/.exec(token);
  if (!m || !m[1] || !m[2]) return false;
  const exp = Number(m[1]);
  if (exp < nowSeconds || exp > nowSeconds + maxTtlSeconds + 60) return false;
  return safeEqual(hmac(secret, `purpose:v1|${purpose}|${subject}|${exp}`), m[2]);
}

// ---------------------------------------------------------------------------
// Share links (QR codes, WhatsApp/SMS, website widget): /s/<surveyId>.<sig>
// The signature proves the link was made by us for this survey, so survey ids can't be guessed into pages.
// ---------------------------------------------------------------------------

export function buildShareToken(secret: string, surveyId: string): string {
  if (!isUuid(surveyId)) throw new Error("invalid survey id");
  return `${surveyId}.${hmac(secret, `share:v1|${surveyId}`)}`;
}

export function verifyShareToken(secrets: readonly string[], token: string): string | null {
  if (typeof token !== "string" || token.length > 80) return null;
  const m = /^([0-9a-f-]{36})\.([A-Za-z0-9_-]{22})$/.exec(token);
  if (!m || !m[1] || !m[2] || !isUuid(m[1])) return null;
  let ok = false;
  for (const secret of secrets) {
    if (secret && safeEqual(hmac(secret, `share:v1|${m[1]}`), m[2])) ok = true;
  }
  return ok ? m[1] : null;
}

// ---------------------------------------------------------------------------
// Kiosk links: /k/<kioskId>.<random secret>. Only sha256(secret) is stored.
// ---------------------------------------------------------------------------

export function parseKioskToken(token: string): { kioskId: string; secret: string } | null {
  if (typeof token !== "string" || token.length > 100) return null;
  const m = /^([0-9a-f-]{36})\.([A-Za-z0-9_-]{43})$/.exec(token);
  if (!m || !m[1] || !m[2] || !isUuid(m[1])) return null;
  return { kioskId: m[1], secret: m[2] };
}

// ---------------------------------------------------------------------------
// Branch tags on share links and rating links: "l=<locationId>.<sig>".
// The signature ties the branch to one survey, so a customer can't move a rating to another branch
// or reuse a tag on another business's survey. The database also checks the branch belongs to the survey's business.
// ---------------------------------------------------------------------------

export function buildLocationTag(secret: string, surveyId: string, locationId: string): string {
  if (!isUuid(surveyId) || !isUuid(locationId)) throw new Error("invalid id");
  return `${locationId}.${hmac(secret, `loc:v1|${surveyId}|${locationId}`)}`;
}

export function verifyLocationTag(secrets: readonly string[], surveyId: string, tag: string | null | undefined): string | null {
  if (typeof tag !== "string" || tag.length > 80 || !isUuid(surveyId)) return null;
  const m = /^([0-9a-f-]{36})\.([A-Za-z0-9_-]{22})$/.exec(tag);
  if (!m || !m[1] || !m[2] || !isUuid(m[1])) return null;
  let ok = false;
  for (const secret of secrets) {
    if (secret && safeEqual(hmac(secret, `loc:v1|${surveyId}|${m[1]}`), m[2])) ok = true;
  }
  return ok ? m[1] : null;
}

// ---------------------------------------------------------------------------
// Testimonial wall: /wall/<accountId>.<sig>. Signed so business ids can't be guessed into pages.
// ---------------------------------------------------------------------------

export function buildWallToken(secret: string, accountId: string): string {
  if (!isUuid(accountId)) throw new Error("invalid account id");
  return `${accountId}.${hmac(secret, `wall:v1|${accountId}`)}`;
}

export function verifyWallToken(secrets: readonly string[], token: string): string | null {
  if (typeof token !== "string" || token.length > 80) return null;
  const m = /^([0-9a-f-]{36})\.([A-Za-z0-9_-]{22})$/.exec(token);
  if (!m || !m[1] || !m[2] || !isUuid(m[1])) return null;
  let ok = false;
  for (const secret of secrets) {
    if (secret && safeEqual(hmac(secret, `wall:v1|${m[1]}`), m[2])) ok = true;
  }
  return ok ? m[1] : null;
}

// ---------------------------------------------------------------------------
// "Did we fix it?" links: "rv=<originalResponseId>.<sig>", bound to the survey, so an answer can only be
// linked to the rating the email was about. The database checks again that such an email was sent.
// ---------------------------------------------------------------------------

export function buildRecoveryTag(secret: string, surveyId: string, responseId: string): string {
  if (!isUuid(surveyId) || !isUuid(responseId)) throw new Error("invalid id");
  return `${responseId}.${hmac(secret, `rec:v1|${surveyId}|${responseId}`)}`;
}

export function verifyRecoveryTag(secrets: readonly string[], surveyId: string, tag: string | null | undefined): string | null {
  if (typeof tag !== "string" || tag.length > 80 || !isUuid(surveyId)) return null;
  const m = /^([0-9a-f-]{36})\.([A-Za-z0-9_-]{22})$/.exec(tag);
  if (!m || !m[1] || !m[2] || !isUuid(m[1])) return null;
  let ok = false;
  for (const secret of secrets) {
    if (secret && safeEqual(hmac(secret, `rec:v1|${surveyId}|${m[1]}`), m[2])) ok = true;
  }
  return ok ? m[1] : null;
}
